import{_ as a,o as t,c as r,ag as l}from"./chunks/framework.CvgP6Fyv.js";const m=JSON.parse('{"title":"Stream Replay","description":"","frontmatter":{},"headers":[],"relativePath":"guides/stream-replay.md","filePath":"guides/stream-replay.md"}'),o={name:"guides/stream-replay.md"};function i(s,e,n,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="stream-replay" tabindex="-1">Stream Replay <a class="header-anchor" href="#stream-replay" aria-label="Permalink to &quot;Stream Replay&quot;">​</a></h1><p>Replay recorded data as live LSL streams for hardware-free development and testing.</p><h2 id="opening-the-stream-manager" tabindex="-1">Opening the Stream Manager <a class="header-anchor" href="#opening-the-stream-manager" aria-label="Permalink to &quot;Opening the Stream Manager&quot;">​</a></h2><p>Click the play-circle icon in the top navigation bar to open the Stream Manager panel.</p><h2 id="file-replay" tabindex="-1">File Replay <a class="header-anchor" href="#file-replay" aria-label="Permalink to &quot;File Replay&quot;">​</a></h2><ol><li>Switch to the <strong>File</strong> tab</li><li>Click <strong>Browse File...</strong> to open the file picker</li><li>Select a recording file (<code>.fif</code>, <code>.h5</code>, <code>.hdf5</code>)</li><li>Review the file metadata (duration, sample rate, channels, events)</li><li>Toggle <strong>Create separate events stream</strong> if you want events on a dedicated LSL outlet (shown when events exist)</li><li>Click <strong>Start Replay</strong></li></ol><h2 id="recording-replay" tabindex="-1">Recording Replay <a class="header-anchor" href="#recording-replay" aria-label="Permalink to &quot;Recording Replay&quot;">​</a></h2><p>The <strong>Recordings</strong> tab lists recordings from the database. Select a recording and click <strong>Start Replay</strong> to stream it.</p><h2 id="moabb-replay" tabindex="-1">MOABB Replay <a class="header-anchor" href="#moabb-replay" aria-label="Permalink to &quot;MOABB Replay&quot;">​</a></h2><ol><li>Switch to the <strong>MOABB</strong> tab and click <strong>Load Datasets</strong> to discover available datasets</li><li>Select a dataset and subject</li><li>Click <strong>Start Stream</strong></li></ol><p>MOABB data downloads automatically on first use.</p><h2 id="active-streams" tabindex="-1">Active Streams <a class="header-anchor" href="#active-streams" aria-label="Permalink to &quot;Active Streams&quot;">​</a></h2><p>Running streams appear at the top of the panel with a source badge (FILE/MOABB), source label, progress bar, and stop button. Multiple streams can run simultaneously. Stream names are prefixed to avoid conflicts with live hardware streams.</p><p>Replay streams appear in <strong>Configure Streams</strong> just like real hardware — select and start recording as usual.</p>',14)])])}const g=a(o,[["render",i]]);export{m as __pageData,g as default};
